VAR edu = TRIM('Loan'[Education] & "")
RETURN
SWITCH(
    TRUE(),
    edu IN {
        "Preschool", "1st-4th", "5th-6th", "7th-8th",
        "9th", "10th", "11th", "12th"
    }, "Below High School",

    edu = "HS-grad", "High School",

    edu IN {
        "Some-college", "Assoc-voc", "Assoc-acdm"
    }, "Some College / Associate",

    edu = "Bachelors", "Bachelor",

    edu IN {
        "Masters", "Doctorate", "Prof-school"
    }, "Postgraduate / Professional",

    "Unknown"
)

